/**
 * @summary Bulk re-run accounting draft generation for the given blocked expense ids
 */
export const retryBlockedExpensesBodyExpenseIdsMax = 200;

export const RetryBlockedExpensesBody = zod.object({
  expenseIds: zod
    .array(zod.number())
    .min(1)
    .max(retryBlockedExpensesBodyExpenseIdsMax),
});

export const RetryBlockedExpensesResponse = zod.object({
  results: zod.array(
    zod.object({
      expenseId: zod.number(),
      result: zod
        .object({
          ok: zod.boolean(),
          created: zod.boolean().optional(),
          manualJournalEntryDraftId: zod.number().optional(),
          reason: zod
            .enum([
              "missing_category",
              "missing_mapping",
              "archived_account",
              "non_postable_account",
              "invalid_payment_method_rule",
              "missing_ap_account",
              "missing_cash_account",
              "other",
            ])
            .optional(),
          message: zod.string().optional(),
        })
        .describe(
          "Task #52 \/ #63 — outcome of an attempt to bridge a source document\n(expense or bill) into a manual journal entry draft. `ok=true` means\na draft is now linked; `created` distinguishes a brand new draft from\nre-returning an existing one (idempotent retry). `ok=false`\ncarries a stable machine-readable `reason` code.\n",
        ),
    }),
  ),
});

